using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.Api.Data; using RaceDay.Api.DTOs; using RaceDay.Api.Models; using RaceDay.Api.Services;
namespace RaceDay.Api.Controllers;
[ApiController,Route("api/events")]
public class EventsController(RaceDayDbContext db,SessionAuth auth):ControllerBase{
 [HttpGet] public async Task<IActionResult> All()=>Ok(await db.Events.AsNoTracking().Select(e=>new EventResponse(e.Id,e.Name,e.Description,e.EventDate,e.Location,e.DistanceKm,e.EventType,e.BannerImageUrl,e.OrganiserId)).ToListAsync());
 [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){var e=await db.Events.Include(x=>x.Categories).SingleOrDefaultAsync(x=>x.Id==id);return e is null?NotFound():Ok(new {e.Id,e.Name,e.Description,e.EventDate,e.Location,e.DistanceKm,e.EventType,e.BannerImageUrl,e.OrganiserId,Categories=e.Categories.Select(c=>new {c.Id,c.EventId,c.Name,c.MinimumAge,c.MaximumAge,c.DistanceKm})});}
 [HttpPost] public async Task<IActionResult> Create(EventRequest r){if(!auth.Is(UserRole.Organiser))return Forbid();var u=auth.Current!;var e=new Event{Name=r.Name,Description=r.Description,EventDate=r.EventDate,Location=r.Location,DistanceKm=r.DistanceKm,EventType=r.EventType,BannerImageUrl=r.BannerImageUrl,OrganiserId=u.Id};db.Events.Add(e);await db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=e.Id},e);}
 [HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,EventRequest r){var e=await db.Events.FindAsync(id);if(e is null)return NotFound();if(!auth.Is(UserRole.Organiser)||e.OrganiserId!=auth.Current!.Id)return Forbid();e.Name=r.Name;e.Description=r.Description;e.EventDate=r.EventDate;e.Location=r.Location;e.DistanceKm=r.DistanceKm;e.EventType=r.EventType;e.BannerImageUrl=r.BannerImageUrl;await db.SaveChangesAsync();return Ok(e);}
 [HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){var e=await db.Events.FindAsync(id);if(e is null)return NotFound();if(!auth.Is(UserRole.Organiser)||e.OrganiserId!=auth.Current!.Id)return Forbid();db.Events.Remove(e);await db.SaveChangesAsync();return NoContent();}
 [HttpPost("{id:int}/categories")] public async Task<IActionResult> Category(int id,CategoryRequest r){var e=await db.Events.FindAsync(id);if(e is null)return NotFound();if(!auth.Is(UserRole.Organiser)||e.OrganiserId!=auth.Current!.Id)return Forbid();var c=new Category{EventId=id,Name=r.Name,MinimumAge=r.MinimumAge,MaximumAge=r.MaximumAge,DistanceKm=r.DistanceKm};db.Categories.Add(c);await db.SaveChangesAsync();return Ok(c);}
}
